"""Byte-exact frame dumper for colour/style analysis."""
import sys, re
sys.path.insert(0,'/tmp/probe')
import sep2 as sep, an

ANSI=re.compile(rb'\x1b(\[[0-9;\-\? ]*[A-Za-z]|P[^\x1b]*\x1b\\|\][^\x07]*\x07|.)')

def esc(b):
    """readable repr: ESC shown as \\e, keep printable."""
    out=[]
    for ch in b:
        if ch==0x1b: out.append('\\e')
        elif ch==0x0d: out.append('\\r')
        elif ch==0x0a: out.append('\\n')
        elif ch==0x00: out.append('\\0')
        elif 32<=ch<127: out.append(chr(ch))
        else: out.append('\\x%02x'%ch)
    return ''.join(out)

def body(frame):
    """strip leading reset-position and trailing cursor moves; return the raw body bytes"""
    b=frame
    b=re.sub(rb'^(\x1b\[\d+[BC])*',b'',b)
    b=re.sub(rb'^\r(\x1b\[2K|\x1b\[1A)*',b'',b)
    b=re.sub(rb'^\x1b\[6n',b'',b)
    m=re.search(rb'(\x1b\[-?\d+A)?(\x1b\[-?\d+D)?\x1b\[\?25[lh]$',b)
    tail=b''
    if m:
        tail=b[m.start():]
        b=b[:m.start()]
    return b,tail

def dump(j,keys=(),cols=80,rows_=24,label='',args=(),wait=0.4,kd=0.16,frames=None,raw=False):
    o,e,rc=sep.run(args,cols=cols,rows=rows_,json_in=j,keys=list(keys)+[b'q'],
                   wait=wait,key_delay=kd,final_wait=0.3)
    ds=an.draws(o)
    print('=== %s   frames=%d rc=%s %s'%(label or (j[:50] if j else str(args)),len(ds),rc,'ERR:'+repr(e[:120]) if e else ''))
    if raw:
        print('  RAWALL:',esc(o))
    sel=range(len(ds)) if frames is None else frames
    for i in sel:
        if i>=len(ds): continue
        f=ds[i]
        bb,tl=body(f)
        print('  --- frame %d  (full raw incl. prefix/tail) ---'%i)
        print('  PRE+BODY+TAIL: '+esc(f))
        print('  ROWS:')
        for ri,r in enumerate(bb.split(b'\r\n')):
            print('    [%02d] %s'%(ri,esc(r)))
    return o,e,ds
